import base64,gzip,re
from pathlib import Path
DATA=''
root=Path('unit-master')
out=root/'app/src/main/java/com/mg/unitmasterx/MainActivity.java'
out.write_bytes(gzip.decompress(base64.b64decode(DATA)))
p=root/'app/build.gradle'
s=p.read_text()
s=re.sub(r"versionCode\s+\d+","versionCode 102",s)
s=re.sub(r"versionName\s+'[^']+'","versionName '1.0.2'",s)
s=s.replace("applicationIdSuffix '.stable'","applicationIdSuffix '.stable2'")
s=s.replace("versionNameSuffix '-stable'","versionNameSuffix '-stable2'")
s=s.replace("manifestPlaceholders = [appLabel: 'Unit Master X Stable']","manifestPlaceholders = [appLabel: 'Unit Master X Stable 2']")
p.write_text(s)
print('Applied v1.0.2 safe activity')
